function renderCalendar(){const m=state.cal,y=m.getFullYear(),mo=m.getMonth(),first=new Date(y,mo,1),start=(first.getDay()+6)%7,days=new Date(y,mo+1,0).getDate(),prev=new Date(y,mo,0).getDate(),cells=Math.ceil((start+days)/7)*7,heads=['H','K','Sze','Cs','P','Szo','V'];let h=heads.map(x=>'<div class="dow">'+x+'</div>').join('');for(let i=0;i<cells;i++){const dn=i-start+1;let d;if(dn<1)d=new Date(y,mo-1,prev+dn);else if(dn>days)d=new Date(y,mo+1,dn-days);else d=new Date(y,mo,dn);const ev=state.jobs.filter(j=>sameDay(j.startAt,d)).sort((a,b)=>D(a.startAt)-D(b.startAt));h+='<div class="day '+(sameDay(d,new Date())?'today':'')+'"><div class="day-num"><button class="secondary" style="padding:2px 6px;font-size:8px;float:right" data-day="'+d.toISOString()+'">+</button>'+d.getDate()+'</div>'+ev.slice(0,4).map(j=>'<button class="day-event" data-cal="'+esc(j.id)+'">'+fmtTime(j.startAt)+' · '+esc(j.customerName)+'</button>').join('')+'</div>'}$('calendarGrid').innerHTML=h;$('calTitle').textContent=new Intl.DateTimeFormat('hu-HU',{month:'long',year:'numeric'}).format(m).replace(/^./,c=>c.toUpperCase());$('calendarDate').textContent=new Intl.DateTimeFormat('hu-HU',{dateStyle:'full'}).format(new Date());document.querySelectorAll('[data-cal]').forEach(b=>b.onclick=()=>openDetail(b.dataset.cal));document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>openNew(b.dataset.day));const t=state.jobs.filter(j=>sameDay(j.startAt,new Date())).sort((a,b)=>D(a.startAt)-D(b.startAt));$('calendarToday').innerHTML=t.length?t.map(j=>'<div class="row"><div><b>'+fmtTime(j.startAt)+' · '+esc(j.customerName)+'</b><p>'+esc(j.car)+' · '+esc(j.serviceName)+'</p></div><span class="badge '+(closed(j)?'ok':'warn')+'">'+(closed(j)?'Lezárt':'Nyitott')+'</span></div>').join(''):'<div class="muted" style="font-size:9px">Nincs mai időpont.</div>';const n=state.jobs.filter(j=>!closed(j)&&D(j.startAt)>new Date()).sort((a,b)=>D(a.startAt)-D(b.startAt)).slice(0,8);$('upcoming').innerHTML=n.length?n.map(j=>'<div class="row"><div><b>'+fmtDate(j.startAt)+' · '+fmtTime(j.startAt)+'</b><p>'+esc(j.customerName)+' · '+esc(j.car)+'</p></div><button class="secondary" data-up="'+esc(j.id)+'">Megnyitás</button></div>').join(''):'<div class="muted" style="font-size:9px">Nincs következő időpont.</div>';document.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>openDetail(b.dataset.up))}
function inventoryRow(x){const s=stockState(x),displayCost=stockDisplayUnitCost(x);return'<tr data-stock="'+esc(x.id)+'"><td><input class="input stock-name" value="'+esc(x.name)+'"></td><td><input class="input stock-category" value="'+esc(x.category||'Egyéb')+'"></td><td><input class="input stock-qty" type="number" step="0.01" value="'+(Number(x.qty)||0)+'"><div class="muted" style="font-size:8px;margin-top:3px">'+esc(x.unit)+'</div></td><td><input class="input stock-min" type="number" step="0.01" value="'+(Number(x.min)||0)+'"></td><td><div style="display:grid;grid-template-columns:1fr 92px 1fr;gap:5px;min-width:260px"><input class="input stock-packqty" type="number" step="0.01" value="'+(Number(x.packQty)||1)+'"><select class="select stock-packunit">'+['db','liter','ml','kg','g'].map(u=>'<option '+((x.packUnit||x.unit)===u?'selected':'')+'>'+u+'</option>').join('')+'</select><input class="input stock-packprice" type="number" step="1" value="'+(Number(x.packPrice)||0)+'"></div><div class="muted" style="font-size:8px;margin-top:3px">kiszerelés mennyiség · egység · ár</div></td><td class="inline-unitcost">'+money(displayCost)+' / '+esc(x.unit)+'</td><td class="inline-value">'+money(stockValue(x))+'</td><td class="inline-status"><span class="badge '+(s==='critical'?'danger':s==='low'?'warn':'ok')+'">'+stockLabel(x)+'</span></td><td><button class="secondary" data-delete-stock="'+esc(x.id)+'">Törlés</button></td></tr>'}
function renderInventory(){const rank={critical:0,low:1,ok:2},search=($('inventorySearch')?.value||'').toLowerCase(),status=$('inventoryStatus')?.value||'all',cat=$('inventoryCategory')?.value||'all',all=state.stock.slice(),filtered=all.filter(x=>(status==='all'||stockState(x)===status)&&(cat==='all'||(x.category||'Egyéb')===cat)&&String(x.name+' '+(x.category||'')).toLowerCase().includes(search)).sort((x,y)=>rank[stockState(x)]-rank[stockState(y)]||String(x.name).localeCompare(String(y.name),'hu')),critical=all.filter(x=>stockState(x)==='critical').length,low=all.filter(x=>stockState(x)==='low').length,cats=[...new Set(all.map(x=>x.category||'Egyéb'))].sort((x,y)=>x.localeCompare(y,'hu'));$('inventoryCategory').innerHTML='<option value="all">Minden kategória</option>'+cats.map(x=>'<option value="'+esc(x)+'" '+(x===cat?'selected':'')+'>'+esc(x)+'</option>').join('');$('inventoryVisualMeta').textContent=filtered.length+' / '+all.length+' tétel · '+critical+' piros · '+low+' sárga';$('dashStockMeta').textContent=all.length+' tétel';$('dashStock').innerHTML=all.length?all.slice().sort((x,y)=>rank[stockState(x)]-rank[stockState(y)]).map(stockCard).join(''):'<div class="muted">Nincs készlet.</div>';$('inventoryVisual').innerHTML=filtered.length?filtered.map(stockCard).join(''):'<div class="recipe-empty">A szűrésnek megfelelő készlet nincs.</div>';$('invCount').textContent=all.length;$('invCritical').textContent=critical;$('invLow').textContent=low;$('invValue').textContent=money(all.reduce((s,x)=>s+stockValue(x),0));$('inventoryEditor').innerHTML=filtered.length?filtered.map(inventoryRow).join(''):'<tr><td colspan="9" class="muted">Nincs találat.</td></tr>';renderRecipes();renderMovements();document.querySelectorAll('#inventoryEditor input,#inventoryEditor select').forEach(el=>el.oninput=()=>{const tr=el.closest('tr'),old=state.stock.find(s=>s.id===tr.dataset.stock);if(!old)return;const x={qty:Number(tr.querySelector('.stock-qty').value)||0,unit:old.unit,min:Number(tr.querySelector('.stock-min').value)||0,packQty:Number(tr.querySelector('.stock-packqty').value)||1,packUnit:tr.querySelector('.stock-packunit').value,packPrice:Number(tr.querySelector('.stock-packprice').value)||0};tr.querySelector('.inline-unitcost').textContent=money(stockDisplayUnitCost(x))+' / '+x.unit;tr.querySelector('.inline-value').textContent=money(stockValue(x));const s=stockState(x);tr.querySelector('.inline-status').innerHTML='<span class="badge '+(s==='critical'?'danger':s==='low'?'warn':'ok')+'">'+stockLabel(x)+'</span>'})}
function stockCard(x){const s=stockState(x),target=Math.max((Number(x.min)||0)*3,1),pct=x.unit==='%'?Math.min(100,Math.max(0,Number(x.qty)||0)):Math.min(100,Math.max(0,(Number(x.qty)||0)/target*100));return'<div class="card stock '+s+'"><div class="stock-top"><b>'+esc(x.name)+'</b><span>'+(Number(x.qty)||0)+' '+esc(x.unit)+'</span></div><div class="bar"><i style="width:'+pct+'%"></i></div><div class="stock-top"><span class="badge '+(s==='critical'?'danger':s==='low'?'warn':'ok')+'">'+stockLabel(x)+'</span><span>'+money(stockValue(x))+'</span></div></div>'}
function renderRecipes(){const targets=SERVICES.map(s=>({key:s.id,name:s.name,kind:'Szolgáltatás'})).concat(EXTRAS.map(e=>({key:recipeKeyForExtra(e.id),name:e.name,kind:'Extra'})));$('recipeCards').innerHTML=targets.map(t=>{const lines=recipeForKey(t.key),cost=lines.reduce((sum,l)=>{const s=state.stock.find(x=>x.id===l.stockId);return sum+(s?Number(l.qty||0)*unitFactor(l.unit)*stockUnitCost(s):0)},0);return'<div class="card recipe-card"><div class="recipe-top"><div><h4>'+esc(t.name)+'</h4><p>'+esc(t.kind)+' · '+lines.length+' anyag</p></div><div class="recipe-total">'+money(cost)+'</div></div>'+(lines.length?lines.map(l=>{const s=state.stock.find(x=>x.id===l.stockId),cost=s?Number(l.qty||0)*unitFactor(l.unit)*stockUnitCost(s):0;return'<div class="recipe-line"><div><b>'+esc(s?.name||'Ismeretlen termék')+'</b><span class="muted"> · '+l.qty+' '+esc(l.unit)+'</span></div><b>'+money(cost)+'</b></div>'}).join(''):'<div class="recipe-empty" style="margin-top:12px">Nincs recept. Kattints a szerkesztéshez.</div>')+'<div class="actions" style="justify-content:space-between"><span class="muted" style="font-size:8px">Záráskor automatikus fogyás</span><button class="secondary" data-edit-recipe="'+esc(t.key)+'">✎ Szerkesztés</button></div></div>'}).join('');document.querySelectorAll('[data-edit-recipe]').forEach(b=>b.onclick=()=>openRecipe(b.dataset.editRecipe))}
function renderMovements(){const a=(state.stockMovements||[]).slice(0,20);$('stockMovements').innerHTML=a.length?a.map(m=>{const s=state.stock.find(x=>x.id===m.stockId),q=Number(m.qty)||0;return'<div class="movement"><div><div class="movement-kind">'+esc(m.kind==='consumption'?'FELHASZNÁLÁS':m.kind==='purchase'?'BESZERZÉS':'VISSZAÍRÁS')+'</div><p>'+fmtDate(m.at)+' · '+fmtTime(m.at)+'</p></div><div><b>'+esc(s?.name||m.stockId)+'</b><p>'+esc(m.reason||'')+'</p></div><div class="qty '+(q>0?'qty-plus':q<0?'qty-minus':'qty-adjust')+'">'+(q>0?'+':'')+q+' '+esc(s?.unit||'db')+'</div></div>'}).join(''):'<div class="recipe-empty">Még nincs készletmozgás.</div>'}
function openRecipe(key){state.recipeTarget=key;const meta=SERVICES.map(s=>({key:s.id,name:s.name})).concat(EXTRAS.map(e=>({key:recipeKeyForExtra(e.id),name:e.name}))).find(x=>x.key===key);$('recipeModalTitle').textContent='Recept · '+(meta?.name||'');$('recipeModalSub').textContent='Felhasználásból számoljuk az anyagköltséget és záráskor a készletfogyást.';$('recipeProduct').innerHTML=state.stock.map(s=>'<option value="'+esc(s.id)+'">'+esc(s.name)+'</option>').join('');$('recipeUnit').innerHTML=['db','liter','ml','kg','g'].map(u=>'<option>'+u+'</option>').join('');$('recipeQty').value='';renderRecipeModalLines();$('recipeModal').classList.add('show')}
function renderRecipeModalLines(){const lines=recipeForKey(state.recipeTarget);$('recipeLines').innerHTML=lines.length?lines.map((l,i)=>{const s=state.stock.find(x=>x.id===l.stockId),cost=s?Number(l.qty)*unitFactor(l.unit)*stockUnitCost(s):0;return'<div class="row"><div><b>'+esc(s?.name||'Ismeretlen termék')+'</b><p>'+l.qty+' '+esc(l.unit)+' · '+money(cost)+'</p></div><button class="secondary" data-remove-recipe="'+i+'">Törlés</button></div>'}).join(''):'<div class="recipe-empty">Még nincs anyag hozzáadva.</div>';const total=lines.reduce((sum,l)=>{const s=state.stock.find(x=>x.id===l.stockId);return sum+(s?Number(l.qty)*unitFactor(l.unit)*stockUnitCost(s):0)},0);$('recipeCost').textContent=money(total)+' / alkalom';document.querySelectorAll('[data-remove-recipe]').forEach(b=>b.onclick=()=>{state.recipes[state.recipeTarget].splice(Number(b.dataset.removeRecipe),1);renderRecipeModalLines()})}
function addRecipeLine(){const id=$('recipeProduct').value,qty=Number($('recipeQty').value)||0,unit=$('recipeUnit').value;if(!id||qty<=0){toast('Adj meg terméket és felhasználási mennyiséget');return}state.recipes[state.recipeTarget]||(state.recipes[state.recipeTarget]=[]);state.recipes[state.recipeTarget].push({stockId:id,qty,unit});$('recipeQty').value='';renderRecipeModalLines()}
function saveRecipe(){save();$('recipeModal').classList.remove('show');renderAll();toast('Anyagrecept mentve')}

function saveInventory(){document.querySelectorAll('#inventoryEditor tr[data-stock]').forEach(tr=>{const old=state.stock.find(s=>s.id===tr.dataset.stock);if(!old)return;const x={...old,name:tr.querySelector('.stock-name').value.trim()||old.name,category:tr.querySelector('.stock-category').value.trim()||old.category,qty:Number(tr.querySelector('.stock-qty').value)||0,min:Number(tr.querySelector('.stock-min').value)||0,packQty:Number(tr.querySelector('.stock-packqty').value)||1,packUnit:tr.querySelector('.stock-packunit').value,packPrice:Number(tr.querySelector('.stock-packprice').value)||0};x.price=stockDisplayUnitCost(x);const diff=x.qty-Number(old.qty||0);if(Math.abs(diff)>1e-9)logMovement(x.id,diff,'adjustment','Kézi készletkorrekció');Object.assign(old,x)});save();renderAll();toast('Készlet mentve')}
function addStock(){$('stockName').value='';$('stockCategory').value='';$('stockQty').value='0';$('stockUnit').value='db';$('stockMin').value='1';$('stockPackQty').value='1';$('stockPackUnit').value='db';$('stockPackPrice').value='0';$('stockUnitCostPreview').textContent='Egységköltség: —';$('stockModalTitle').textContent='Új készlettétel';$('stockModal').classList.add('show')}
function previewNewStockCost(){const x={packQty:Number($('stockPackQty').value)||0,packUnit:$('stockPackUnit').value,packPrice:Number($('stockPackPrice').value)||0,unit:$('stockUnit').value};const u=x.packQty?stockDisplayUnitCost(x):0;$('stockUnitCostPreview').textContent=u?('Egységköltség: '+money(u)+' / '+x.unit):'Egységköltség: —'}
function saveStock(){const x={id:uid('ST'),name:$('stockName').value.trim()||'Új termék',category:$('stockCategory').value.trim()||'Egyéb',qty:Number($('stockQty').value)||0,unit:$('stockUnit').value,min:Number($('stockMin').value)||0,packQty:Number($('stockPackQty').value)||1,packUnit:$('stockPackUnit').value,packPrice:Number($('stockPackPrice').value)||0};x.price=stockDisplayUnitCost(x);state.stock.push(x);if(x.qty)logMovement(x.id,x.qty,'purchase','Nyitókészlet');save();$('inventorySearch').value='';$('inventoryStatus').value='all';$('inventoryCategory').value='all';$('stockModal').classList.remove('show');renderAll();toast(x.name+' · készlettétel hozzáadva')}
function restockOpen(){const sel=$('restockProduct');sel.innerHTML=state.stock.length?state.stock.map(s=>'<option value="'+esc(s.id)+'">'+esc(s.name)+'</option>').join(''):'<option value="">Nincs készlettétel</option>';$('restockQty').value='';$('restockCost').value='';$('restockNote').value='';renderRestockInfo();$('restockModal').classList.add('show')}
function renderRestockInfo(){const s=state.stock.find(x=>x.id===$('restockProduct')?.value);$('restockInfo').textContent=s?('Jelenlegi készlet: '+s.qty+' '+s.unit+' · átlagos egységköltség: '+money(stockDisplayUnitCost(s))+' / '+s.unit):'Nincs kiválasztott termék.'}
function saveRestock(){const s=state.stock.find(x=>x.id===$('restockProduct').value),q=Number($('restockQty').value)||0;if(!s||q<=0){toast('Adj meg terméket és mennyiséget');return}const addedCost=Number($('restockCost').value);const oldBase=Math.max(0,Number(s.qty)||0)*unitFactor(s.unit);const newBase=q*unitFactor(s.unit);const oldValue=oldBase*stockUnitCost(s);const batchValue=Number.isFinite(addedCost)&&addedCost>0?addedCost:newBase*stockUnitCost(s);const avgBase=newBase+oldBase>0?(oldValue+batchValue)/(newBase+oldBase):0;s.qty=Number(s.qty)+q;s.packQty=1;s.packUnit=s.unit;s.packPrice=avgBase*unitFactor(s.unit);s.price=stockDisplayUnitCost(s);logMovement(s.id,q,'purchase',$('restockNote').value.trim()||'Beszerzés');save();$('restockModal').classList.remove('show');renderAll();toast('Beszerzés rögzítve · átlagár frissítve')}
function deleteStock(id){const used=Object.values(state.recipes||{}).some(lines=>Array.isArray(lines)&&lines.some(l=>l.stockId===id))||(state.jobs||[]).some(j=>(j.inventoryConsumption||[]).some(x=>x.stockId===id));if(used){toast('A terméket recept vagy munkatörténet használja. Előbb távolítsd el a receptekből.');return}if(!confirm('Biztosan törlöd ezt a készlettételt?'))return;state.stock=state.stock.filter(x=>x.id!==id);save();renderAll();toast('Készlettétel törölve')}
function renderAnalytics(){const n=new Date(),a=state.jobs.filter(j=>closed(j)&&D(j.startAt).getFullYear()===n.getFullYear()&&D(j.startAt).getMonth()===n.getMonth()),rev=a.reduce((s,j)=>s+j.total,0),cost=a.reduce((s,j)=>s+j.cost,0),svc={},paym={};a.forEach(j=>{svc[j.serviceName]=(svc[j.serviceName]||0)+j.total;paym[j.paymentMethod||'Nincs rögzítve']=(paym[j.paymentMethod||'Nincs rögzítve']||0)+j.total});$('aRevenue').textContent=money(rev);$('aCost').textContent=money(cost);$('aMargin').textContent=money(rev-cost);$('aAvg').textContent=money(a.length?rev/a.length:0);$('serviceMix').innerHTML=Object.entries(svc).map(x=>'<div class="row"><div><b>'+esc(x[0])+'</b><p>'+a.filter(j=>j.serviceName===x[0]).length+' munka</p></div><span class="money">'+money(x[1])+'</span></div>').join('')||'<div class="muted">Nincs adat.</div>';$('paymentMix').innerHTML=Object.entries(paym).map(x=>'<div class="row"><b>'+esc(x[0])+'</b><span class="money">'+money(x[1])+'</span></div>').join('')||'<div class="muted">Nincs adat.</div>';$('financeTable').innerHTML=a.map(j=>'<tr><td>'+fmtDate(j.startAt)+'</td><td>'+esc(j.customerName)+'</td><td>'+esc(j.serviceName)+'</td><td>'+money(j.total)+'</td><td>'+money(j.cost)+'</td><td>'+money(j.total-j.cost)+'</td></tr>').join('')||'<tr><td colspan="6" class="muted">Nincs lezárt munka.</td></tr>'}
function renderDashboard(){const n=new Date(),t=state.jobs.filter(j=>sameDay(j.startAt,n)).sort((a,b)=>D(a.startAt)-D(b.startAt)),m=state.jobs.filter(j=>closed(j)&&D(j.startAt).getFullYear()===n.getFullYear()&&D(j.startAt).getMonth()===n.getMonth()),rev=m.reduce((s,j)=>s+j.total,0),today=t.filter(closed),open=state.jobs.filter(j=>!closed(j));$('sToday').textContent=money(today.reduce((s,j)=>s+j.total,0));$('sTodayJobs').textContent=today.length+' lezárt munka';$('sMonth').textContent=money(rev);$('sMonthJobs').textContent=m.length+' lezárt munka';$('sOpen').textContent=open.length;$('sAvg').textContent=money(m.length?rev/m.length:0);$('todayPlanLabel').textContent=t.length+' időpont';$('todayJobs').innerHTML=t.length?t.map(j=>'<div class="row"><div><b>'+fmtTime(j.startAt)+'–'+fmtTime(j.endAt)+' · '+esc(j.customerName)+'</b><p>'+esc(j.car)+' · '+esc(j.serviceName)+'</p></div><div><span class="badge '+(closed(j)?'ok':'warn')+'">'+(closed(j)?'Lezárt':'Nyitott')+'</span><div class="money">'+money(j.total)+'</div></div></div>').join(''):'<div class="muted" style="font-size:9px">Ma nincs beírt időpont.</div>';const pct=Math.min(100,state.goal?rev/state.goal*100:0);$('goalLabel').textContent=money(rev)+' / '+money(state.goal);$('goalBar').style.width=pct+'%';$('goalText').textContent=pct>=100?'A havi cél teljesítve.':pct.toFixed(0)+'% · '+money(state.goal-rev)+' van hátra.'}
function renderSettings(){$('goalInput').value=state.goal;$('cloudStateLabel').textContent='LOCAL';$('cloudSettings').innerHTML='<b>Stabil helyi mód.</b><br>Vercel API és Service Worker nincs a rendszerben. A felhőszinkron külön rétegként kerül rá, miután a helyi működést leteszteltük.'}
function printJob(id){const j=state.jobs.find(x=>x.id===id),ph=state.photos[id]||[];if(!j)return;const sub=j.servicePrice+(j.extras||[]).reduce((s,x)=>s+Number(x.price||0),0);$('printSheet').innerHTML='<div class="print-page"><div class="print-header"><div class="print-brand"><div><img class="print-logo" src="./assets/dtail-logo.png" alt="D-Tail Studio"><div class="print-sub">Premium detailing · A részletek számítanak.</div></div></div><div class="print-id"><b>'+esc(j.id)+'</b>'+fmtDate(j.startAt)+'<br>'+fmtTime(j.startAt)+'–'+fmtTime(j.endAt)+'</div></div><div class="print-grid"><div class="print-card"><h4>Ügyfél</h4><p><b>'+esc(j.customerName)+'</b><br>'+esc(j.phone||'—')+'</p></div><div class="print-card"><h4>Jármű</h4><p><b>'+esc(j.car)+'</b><br>'+esc(j.plate||'—')+' · '+(j.year||'—')+' · '+(j.km?Number(j.km).toLocaleString('hu-HU')+' km':'—')+'</p></div></div><div class="print-card"><h4>Szolgáltatás és tételek</h4><table class="print-items"><thead><tr><th>Tétel</th><th>Érték</th></tr></thead><tbody><tr><td>'+esc(j.serviceName)+'</td><td>'+money(j.servicePrice)+'</td></tr>'+(j.extras||[]).map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+money(x.price)+'</td></tr>').join('')+'</tbody></table><div class="print-total"><div class="print-total-row"><span>Részösszeg</span><b>'+money(sub)+'</b></div><div class="print-total-row"><span>Kedvezmény</span><b>−'+money(j.discount)+'</b></div><div class="print-total-row final"><span>Fizetendő</span><b>'+money(j.total)+'</b></div><div class="print-total-row"><span>Fizetési mód</span><b>'+esc(j.paymentMethod||'—')+'</b></div></div></div><div class="print-grid" style="margin-top:7mm"><div class="print-card"><h4>Megjegyzés</h4><p>'+esc(j.note||'Nincs megjegyzés.').replace(/\\n/g,'<br>')+'</p></div><div class="print-card"><h4>Státusz</h4><p><b>'+((closed(j))?'LEZÁRVA':'NYITOTT')+'</b><br>Anyagköltség: '+money(j.cost)+'</p></div></div><div class="print-checks"><div class="check">'+(j.checklist?.before?'☑':'☐')+' BEFORE</div><div class="check">'+(j.checklist?.damage?'☑':'☐')+' Sérülés</div><div class="check">'+(j.checklist?.after?'☑':'☐')+' AFTER</div></div>'+(ph.length?'<div class="print-photos">'+ph.slice(0,6).map(p=>'<div class="print-photo"><img src="'+p.data+'"><small>'+esc(p.label||'Fotó')+'</small></div>').join('')+'</div>':'')+'<div class="print-footer"><span>D-Tail Studio · '+esc(j.id)+'</span><span>Generálva: '+new Intl.DateTimeFormat('hu-HU',{dateStyle:'medium',timeStyle:'short'}).format(new Date())+'</span></div></div>';window.print()}
function printReport(){const n=new Date(),a=state.jobs.filter(j=>closed(j)&&D(j.startAt).getFullYear()===n.getFullYear()&&D(j.startAt).getMonth()===n.getMonth()),rev=a.reduce((s,j)=>s+j.total,0),cost=a.reduce((s,j)=>s+j.cost,0);$('printSheet').innerHTML='<div class="print-page"><div class="print-header"><div class="print-brand"><div class="print-mark">D-Tail</div><div><div class="print-title">D-Tail Studio</div><div class="print-sub">Havi üzleti riport</div></div></div><div class="print-id"><b>'+new Intl.DateTimeFormat('hu-HU',{month:'long',year:'numeric'}).format(n)+'</b></div></div><div class="print-grid"><div class="print-card"><h4>Havi bevétel</h4><p style="font-size:18px"><b>'+money(rev)+'</b></p></div><div class="print-card"><h4>Becsült fedezet</h4><p style="font-size:18px"><b>'+money(rev-cost)+'</b></p></div></div><div class="print-card"><h4>Havi munkák</h4><table class="print-items"><thead><tr><th>Dátum</th><th>Ügyfél</th><th>Szolgáltatás</th><th>Bevétel</th><th>Anyag</th></tr></thead><tbody>'+a.map(j=>'<tr><td>'+fmtDate(j.startAt)+'</td><td>'+esc(j.customerName)+'</td><td>'+esc(j.serviceName)+'</td><td>'+money(j.total)+'</td><td>'+money(j.cost)+'</td></tr>').join('')+'</tbody></table></div></div>';window.print()}
function exportData(){const x={version:43,exportedAt:new Date().toISOString(),jobs:state.jobs,customers:state.customers,cars:state.cars,stock:state.stock,photos:state.photos,goal:state.goal,recipes:state.recipes,stockMovements:state.stockMovements},a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(x,null,2)],{type:'application/json'}));a.download='dtail-studio-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function importJson(file){file.text().then(t=>{const x=JSON.parse(t);state.jobs=migrateJobs(x.jobs);state.customers=x.customers||[];state.cars=x.cars||[];state.stock=normalizeStock(x.stock);state.photos=x.photos||{};state.goal=Number(x.goal)||1000000;state.recipes=x.recipes||defaultRecipes();state.stockMovements=Array.isArray(x.stockMovements)?x.stockMovements:[];state.recipes=x.recipes||defaultRecipes();state.stockMovements=Array.isArray(x.stockMovements)?x.stockMovements:[];save();renderAll();toast('Mentés betöltve')}).catch(()=>toast('Hibás JSON'))}
function renderAll(){greeting();renderDashboard();renderJobs();renderCustomers();renderCalendar();renderInventory();renderAnalytics();renderSettings()}
