function boot(){try{load();renderAll();setTimeout(()=>{$('boot')?.classList.add('hide');setTimeout(()=>$('boot')?.remove(),450)},400)}catch(e){console.error('D-Tail boot',e);$('boot')?.classList.add('hide')}}
