 $('inventorySearch').oninput=renderInventory;$('inventoryStatus').onchange=renderInventory;$('inventoryCategory').onchange=renderInventory;$('stockRestock').onclick=restockOpen;$('restockProduct').onchange=renderRestockInfo;$('restockQty').oninput=renderRestockInfo;$('restockCost').oninput=renderRestockInfo;$('restockSave').onclick=saveRestock;$('recipeAddLine').onclick=addRecipeLine;$('recipeSave').onclick=saveRecipe;$('stockPackQty').oninput=previewNewStockCost;$('stockPackUnit').onchange=previewNewStockCost;$('stockPackPrice').oninput=previewNewStockCost;$('stockUnit').onchange=previewNewStockCost;$('saveInventory').onclick=saveInventory;$('inventoryEditor').onclick=e=>{const b=e.target.closest('[data-delete-stock]');if(b)deleteStock(b.dataset.deleteStock)};
 $('saveCustomerBtn').onclick=saveCustomer;$('saveStockBtn').onclick=saveStock;$('printReport').onclick=printReport;$('exportData').onclick=exportData;$('importFile').onchange=e=>e.target.files[0]&&importJson(e.target.files[0]);
 $('importLegacy').onclick=()=>{state.jobs=migrateJobs(read('dtail_jobs',[]));state.customers=read('dtail_customers',[]);const s=read('dtail_inventory_v2',[]);state.stock=normalizeStock(s.length?s:DEFAULT_STOCK);save();renderAll();toast('Régi adatok importálva')};
 $('clearLocal').onclick=()=>{if(confirm('A helyi D-Tail adatok törlődnek. Folytatod?')){localStorage.removeItem(KEY);location.reload()}};
